<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea @bind="_content" @bind:event="oninput" rows="12" class="form-control mb-3"
          placeholder="Type your notes here..."></textarea>

<div class="d-flex align-items-center gap-2 mb-3">
    <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
    <button class="btn btn-danger" @onclick="ClearAsync">Clear</button>
    @if (_lastSaved is not null)
    {
        <span class="text-muted">Last saved at @_lastSaved.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string _content = string.Empty;
    private string _savedSnapshot = string.Empty;
    private DateTime? _lastSaved;
    private NotepadInterop? _interop;
    private DotNetObjectReference<Notepad>? _dotNetRef;
    private System.Threading.Timer? _autoSaveTimer;

    private bool IsDirty => _content != _savedSnapshot;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            _dotNetRef = DotNetObjectReference.Create(this);

            var saved = await _interop.InitializeAsync(_dotNetRef);
            if (!string.IsNullOrEmpty(saved))
            {
                _content = saved;
                _savedSnapshot = saved;
                _lastSaved = DateTime.Now;
                StateHasChanged();
            }

            _autoSaveTimer = new System.Threading.Timer(
                _ => _ = InvokeAsync(AutoSaveAsync),
                null,
                TimeSpan.FromSeconds(30),
                TimeSpan.FromSeconds(30));
        }
        else if (_interop is not null)
        {
            await UpdateDirtyStateAsync();
        }
    }

    private async Task UpdateDirtyStateAsync()
    {
        try
        {
            var module = await JS.InvokeAsync<IJSObjectReference>("import", NotepadInterop.ModulePath);
            await module.InvokeVoidAsync("setDirty", IsDirty);
            await module.DisposeAsync();
        }
        catch (JSDisconnectedException) { }
    }

    private async Task AutoSaveAsync()
    {
        if (IsDirty)
        {
            await SaveContentAsync();
            StateHasChanged();
        }
    }

    private async Task SaveNowAsync()
    {
        await SaveContentAsync();
    }

    private async Task SaveContentAsync()
    {
        if (_interop is null) return;
        await _interop.SaveAsync(_content);
        _savedSnapshot = _content;
        _lastSaved = DateTime.Now;
        await UpdateDirtyStateAsync();
    }

    private async Task ClearAsync()
    {
        if (_interop is null) return;
        _content = string.Empty;
        _savedSnapshot = string.Empty;
        _lastSaved = null;
        await _interop.ClearAsync();
        await UpdateDirtyStateAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_autoSaveTimer is not null)
            await _autoSaveTimer.DisposeAsync();

        if (_interop is not null)
            await _interop.DisposeAsync();

        _dotNetRef?.Dispose();
    }
}

